  layout(location = 9) in vec3 v_tangent;
  layout(location = 10) in vec3 v_bitangent;
  layout(set = 1, binding = 7) uniform sampler2D normalMap;
  #define NORMAL_UV v_uv
#endif
#define PBR_UV v_uv
#if USE_PBR_MAP
  layout(set = 1, binding = 8) uniform sampler2D pbrMap;
#endif
#if USE_METALLIC_ROUGHNESS_MAP
  layout(set = 1, binding = 9) uniform sampler2D metallicRoughnessMap;
#endif
#if USE_OCCLUSION_MAP
  layout(set = 1, binding = 10) uniform sampler2D occlusionMap;
#endif
